      "anchor": "public record Scan(int radius, int totalPositions, int scannedPositions, int loadedPositions,",
      "insert": "    public int coveragePercent() {\n        if (totalPositions == 0) return 0;\n        return (int) (100 * scannedPositions / totalPositions);\n    }"
